<?php
declare(strict_types=1);
session_name('HOSTLOJA_ADMIN');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off','httponly'=>true,'samesite'=>'Strict']);
session_start();
require_once __DIR__ . '/store.php';
const ADMIN_HASH = '$2y$12$iHqxgIGamroxXWo3WIqq3OUJjhkB4VIjmNq5H261E9NASJt5rppXi';
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: same-origin');
header('Cache-Control: no-store, private');
function out(array $data, int $status=200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode($data, JSON_UNESCAPED_UNICODE); exit; }
function token_ok(): bool { return isset($_POST['csrf'], $_SESSION['csrf']) && is_string($_POST['csrf']) && hash_equals($_SESSION['csrf'], $_POST['csrf']); }
if (!isset($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32));
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'login') {
    if (!token_ok()) { http_response_code(403); $error='Sessão expirada. Atualize a página.'; }
    else {
        $attempts = (int)($_SESSION['attempts'] ?? 0);
        if ($attempts >= 8) { http_response_code(429); $error='Muitas tentativas. Aguarde e tente novamente.'; }
        elseif (password_verify((string)($_POST['password'] ?? ''), ADMIN_HASH)) { session_regenerate_id(true); $_SESSION['admin']=true; $_SESSION['csrf']=bin2hex(random_bytes(32)); $_SESSION['attempts']=0; header('Location: gestor.php'); exit; }
        else { $_SESSION['attempts']=$attempts+1; $error='Senha incorreta.'; }
    }
}
if (isset($_GET['logout'])) { $_SESSION=[]; session_destroy(); header('Location: gestor.php'); exit; }
if (($_SESSION['admin'] ?? false) === true && $_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') !== 'login') {
    if (!token_ok()) out(['ok'=>false,'message'=>'Sessão inválida. Atualize a página.'], 403);
    $products=hostloja_products(); $action=(string)($_POST['action'] ?? '');
    if ($action==='save') {
        $name=trim((string)($_POST['name'] ?? '')); $price=str_replace(',','.',(string)($_POST['price'] ?? '')); $description=trim((string)($_POST['description'] ?? '')); $days=trim((string)($_POST['duration'] ?? ''));
        if (strlen($description)>880 || strlen($days)>200) out(['ok'=>false,'message'=>'Descrição ou duração muito longa.'],422);
        if ($name==='' || strlen($name)>360 || !is_numeric($price) || (float)$price<0 || (float)$price>1000000) out(['ok'=>false,'message'=>'Confira o nome e o preço.'],422);
        $products[]=['id'=>bin2hex(random_bytes(6)),'name'=>$name,'price'=>round((float)$price,2),'description'=>$description,'duration'=>$days,'emoji'=>'✦'];
        if (!hostloja_save($products)) out(['ok'=>false,'message'=>'Não foi possível salvar no JSON. Verifique a permissão da pasta data.'],500);
        out(['ok'=>true,'message'=>'Produto adicionado com sucesso.','products'=>$products]);
    }
    if ($action==='delete') {
        $id=(string)($_POST['id'] ?? ''); $before=count($products); $products=array_values(array_filter($products,static fn($p)=>(string)$p['id']!==$id));
        if ($before===count($products)) out(['ok'=>false,'message'=>'Produto não encontrado.'],404);
        if (!hostloja_save($products)) out(['ok'=>false,'message'=>'Não foi possível atualizar o JSON.'],500);
        out(['ok'=>true,'message'=>'Produto removido.','products'=>$products]);
    }
    out(['ok'=>false,'message'=>'Ação inválida.'],400);
}
$logged=($_SESSION['admin'] ?? false)===true;
if ($logged && !isset($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32));
$products=hostloja_products();
function e(string $s): string { return htmlspecialchars($s,ENT_QUOTES,'UTF-8'); }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Gestor | HOST LOJA</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"><style>.admin-page{min-height:100vh;background:#f3f8f4;padding:48px 18px}.admin-wrap{max-width:980px;margin:auto}.admin-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.admin-top h1{font:800 28px Manrope;margin:0}.admin-top p{color:#728278;margin:7px 0}.admin-panel{background:#fff;border:1px solid #e3eee6;border-radius:22px;padding:26px;box-shadow:0 18px 50px #164e2d0b}.login-panel{max-width:430px;margin:8vh auto}.admin-form{display:grid;grid-template-columns:1fr 170px;gap:13px}.admin-form label{font-size:11px;font-weight:800;color:#476052;display:grid;gap:7px}.admin-form input{width:100%;height:46px;border:1px solid #dce9df;border-radius:11px;padding:0 13px;outline:none}.admin-form input:focus{border-color:#0b965b;box-shadow:0 0 0 3px #0b965b16}.admin-form .wide{grid-column:1/-1}.admin-form button,.admin-primary{border:0;border-radius:11px;background:#078b52;color:#fff;padding:0 18px;height:46px;font-weight:800}.admin-form button{align-self:end}.admin-list{margin-top:25px;display:grid;gap:10px}.admin-product{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;border:1px solid #e7eee9;border-radius:13px}.admin-product b{display:block}.admin-product small{color:#728278}.delete-product{border:1px solid #f1d8d8;color:#b63c3c;background:#fff;border-radius:9px;padding:9px 12px;font-weight:700}.admin-message{margin:12px 0;color:#b63c3c;font-size:13px}.admin-foot{color:#839087;font-size:11px;margin-top:18px}.admin-link{color:#0b8f55;font-size:12px;font-weight:800}@media(max-width:650px){.admin-form{grid-template-columns:1fr}.admin-form .wide{grid-column:auto}.admin-form button{width:100%}.admin-product{align-items:flex-start}.admin-top{align-items:flex-start;gap:12px}.admin-top h1{font-size:22px}}</style></head><body><div class="admin-page"><div class="admin-wrap"><?php if (!$logged): ?><div class="admin-panel login-panel"><a class="logo" href="index.php"><span class="logo-icon">H<span>+</span></span><span><b>HOST</b><small>LOJA</small></span></a><div class="eyebrow" style="margin-top:34px"><i></i> ÁREA RESTRITA</div><h1 style="font:800 28px Manrope;margin:12px 0 8px">Acesso ao gestor</h1><p style="color:#728278;font-size:13px">Entre com sua senha administrativa para gerenciar a loja.</p><?php if(isset($error)): ?><div class="admin-message"><?=e($error)?></div><?php endif; ?><form method="post" autocomplete="off" class="admin-form" style="grid-template-columns:1fr"><input type="hidden" name="action" value="login"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Senha de acesso<input type="password" name="password" required autocomplete="current-password" placeholder="Digite sua senha"></label><button type="submit">Entrar no gestor <span>→</span></button></form><div class="admin-foot">Acesso protegido por sessão segura.</div></div><?php else: ?><div class="admin-top"><div><div class="eyebrow"><i></i> PAINEL ADMINISTRATIVO</div><h1>Gestor HOST LOJA</h1><p>Cadastre e remova os produtos exibidos na loja.</p></div><a class="admin-link" href="?logout=1">Sair ↗</a></div><div class="admin-panel"><h2 style="font:800 19px Manrope;margin:0 0 18px">Adicionar produto</h2><form class="admin-form" id="productForm"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save"><label class="wide">Nome do produto<input name="name" maxlength="90" required placeholder="Ex.: ACESSO AO BOT HOST MB — 15 DIAS"></label><label>Preço (R$)<input name="price" inputmode="decimal" required placeholder="0,00"></label><label>Duração / tipo<input name="duration" maxlength="50" placeholder="Ex.: 15 dias ou KEY"></label><label class="wide">Descrição<input name="description" maxlength="220" placeholder="Detalhes que aparecerão na loja"></label><button type="submit">Adicionar à loja +</button></form><div id="adminNotice" class="admin-foot" aria-live="polite"></div><div class="admin-list" id="adminList"><?php foreach($products as $p): ?><div class="admin-product" data-id="<?=e((string)$p['id'])?>"><div><b><?=e((string)$p['name'])?></b><small>R$ <?=number_format((float)$p['price'],2,',','.')?> · <?=e((string)($p['duration'] ?? ''))?></small></div><button class="delete-product" data-delete="<?=e((string)$p['id'])?>">Apagar</button></div><?php endforeach; ?></div></div><p class="admin-foot">Os dados são armazenados em <code>data/products.json</code>. Mantenha a pasta data com permissão de escrita.</p><?php endif; ?></div></div><?php if($logged): ?><script>const csrf=<?=json_encode($_SESSION['csrf'])?>;const list=document.getElementById('adminList');const notice=document.getElementById('adminNotice');async function send(data){const body=new URLSearchParams(data);const r=await fetch('gestor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Falha ao salvar');return j}function paint(items){list.innerHTML=items.map(p=>'<div class="admin-product" data-id="'+String(p.id).replace(/[&<>"']/g,'')+'"><div><b>'+safe(p.name)+'</b><small>R$ '+Number(p.price).toFixed(2).replace('.',',')+' · '+safe(p.duration||'')+'</small></div><button class="delete-product" data-delete="'+String(p.id).replace(/[&<>"']/g,'')+'">Apagar</button></div>').join('')}function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}document.getElementById('productForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);f.set('csrf',csrf);try{const j=await send(Object.fromEntries(f.entries()));paint(j.products);e.currentTarget.reset();notice.textContent=j.message}catch(err){notice.textContent=err.message}});list.addEventListener('click',async e=>{const b=e.target.closest('[data-delete]');if(!b)return;if(!confirm('Apagar este produto da loja?'))return;try{const j=await send({action:'delete',id:b.dataset.delete,csrf});paint(j.products);notice.textContent=j.message}catch(err){notice.textContent=err.message}});</script><?php endif; ?></body></html>
